import base64,zlib,json,re,genanki
rows=json.loads(zlib.decompress(base64.b64decode("")))
basic=genanki.Model(1770000006101,"MSK Lecture 6 Basic (Somatic & Autonomic)",fields=[{"name":"Front"},{"name":"Back"}],templates=[{"name":"Card 1","qfmt":"{{Front}}","afmt":"{{FrontSide}}<hr id=answer>{{Back}}"}])
cloze=genanki.Model(1770000006102,"MSK Lecture 6 Cloze (Somatic & Autonomic)",model_type=genanki.Model.CLOZE,fields=[{"name":"Text"}],templates=[{"name":"Cloze","qfmt":"{{cloze:Text}}","afmt":"{{cloze:Text}}"}])
deck=genanki.Deck(1770000006100,"MSK Week 13::Lecture 6 - Somatic & Autonomic PNS")
for row in rows:
    typ,*fields=row
    deck.add_note(genanki.Note(model=basic if typ==0 else cloze,fields=fields))
assert len(deck.notes)==100
out="weeks/week13/MSK_Week13_Lecture6_Somatic_Autonomic_100_Text_Cards.apkg"
genanki.Package(deck).write_to_file(out)
print("Created",out,"with",len(deck.notes),"notes")
